@using sv_c0e44cfa3ea54504b8d98f2cd289921c.Models

<div class="step-indicator d-flex align-items-center justify-content-between mb-4">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i;
        <div class="step-item text-center flex-fill @GetStepClass(step)"
             role="button"
             @onclick="() => HandleStepClick(step)">
            <div class="step-circle mx-auto mb-1 @GetCircleClass(step)">
                @if (CompletedSteps.Contains(step) && step != CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </div>
            <div class="step-label small">@StepNames[step]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector flex-fill @(CompletedSteps.Contains(step) ? "completed" : "")"></div>
        }
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed clickable";
        return "future";
    }

    private string GetCircleClass(int step)
    {
        if (step == CurrentStep) return "bg-primary text-white";
        if (CompletedSteps.Contains(step)) return "bg-success text-white";
        return "bg-light text-muted border";
    }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

