toolArgs.file_text:
.step-indicator {
    padding: 1rem 0;
}

.step-item {
    position: relative;
    min-width: 80px;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.85rem;
    transition: all 0.2s;
}

.step-connector {
    height: 3px;
    background-color: #dee2e6;
    margin: 0 -0.5rem;
    align-self: flex-start;
    margin-top: 18px;
    max-width: 60px;
    transition: background-color 0.2s;
}

.step-connector.completed {
    background-color: #198754;
}

.step-item.future {
    opacity: 0.45;
}

.step-item.clickable {
    cursor: pointer;
}

.step-item.clickable:hover .step-circle {
    transform: scale(1.1);
}

.step-label {
    white-space: nowrap;
}

